mapper.select:
SELECT A.* FROM( SELECT T.* , ROW_NUMBER() OVER (ORDER BY result_score DESC) AS game_rank FROM ( SELECT a.start_seq, a.user_uuid, aa.user_nickname, a.game_play_time, a.game_wave, a.result_score AS result_score, a.epic_skill_1, a.epic_skill_1_level, a.epic_skill_2, a.epic_skill_2_level, (a.ar_legend + a.sniping_legend + a.shotgun_legend) AS legend_count, (a.ar_mythology + a.sniping_mythology + a.shotgun_mythology) AS mythology_count, (a.ar_beginning + a.sniping_beginning + a.shotgun_beginning) AS beginning_count, (SELECT ADDDATE(CURDATE(), - WEEKDAY(CURDATE()) + 0 )) as rank_start_date, (SELECT ADDDATE(CURDATE(), - WEEKDAY(CURDATE()) + 6 )) as rank_end_date, ROW_NUMBER() OVER (PARTITION BY user_uuid ORDER BY result_score DESC) AS RankNo FROM game_max_result_data a LEFT JOIN user_data aa ON a.user_uuid = aa.user_uuid WHERE a.game_mode = #{game_mode} AND a.game_level = #{game_level} AND aa.use_yn = 'Y' AND NOT (aa.user_position = 'admin') AND a.game_result IN ('clear', 'Failed') ORDER by result_score DESC ) T WHERE RankNo = 1
) A
WHERE A.user_uuid = #{user_uuid}

SELECT A.* FROM( SELECT T.* , ROW_NUMBER() OVER (ORDER BY result_score DESC) AS game_rank FROM ( SELECT a.start_seq, a.user_uuid, aa.user_nickname, a.game_play_time, a.game_wave, a.result_score AS result_score, a.epic_skill_1, a.epic_skill_1_level, a.epic_skill_2, a.epic_skill_2_level, (a.ar_legend + a.sniping_legend + a.shotgun_legend) AS legend_count, (a.ar_mythology + a.sniping_mythology + a.shotgun_mythology) AS mythology_count, (a.ar_beginning + a.sniping_beginning + a.shotgun_beginning) AS beginning_count, (SELECT ADDDATE(CURDATE(), - WEEKDAY(CURDATE()) + 0 )) as rank_start_date, (SELECT ADDDATE(CURDATE(), - WEEKDAY(CURDATE()) + 6 )) as rank_end_date, ROW_NUMBER() OVER (PARTITION BY user_uuid ORDER BY result_score DESC) AS RankNo FROM game_week_result_data a LEFT JOIN user_data aa ON a.user_uuid = aa.user_uuid WHERE a.game_mode = #{game_mode} AND a.game_level = #{game_level} AND aa.use_yn = 'Y' AND NOT (aa.user_position = 'admin') AND a.game_result IN ('clear', 'Failed') and date_format(ins_date,'%Y-%m-%d') BETWEEN (SELECT ADDDATE(CURDATE(), - WEEKDAY(CURDATE()) + 0 )) AND (SELECT ADDDATE(CURDATE(), - WEEKDAY(CURDATE()) + 6 )) ORDER by result_score DESC ) T WHERE RankNo = 1
) A
WHERE A.user_uuid = #{user_uuid}

SELECT b.user_rank, b.user_level_experience_max, b.user_level, b.user_nickname
FROM (

         SELECT a.user_uuid, a.user_nickname, RANK() OVER(ORDER BY a.user_level_experience_max DESC) as user_rank, a.user_level_experience_max, a.user_level
         FROM user_data a

     ) b
WHERE user_uuid = #{user_uuid}

SELECT *
FROM game_mode_data
WHERE game_mode = #{game_mode}
  AND game_level = #{game_level}

SELECT *
FROM game_max_result_data
WHERE user_uuid = #{user_uuid}
  AND game_mode = #{game_mode}
  AND game_level = #{game_level}
  AND DATE_FORMAT(ins_date, '%Y-%m-%d') BETWEEN
        (SELECT ADDDATE(CURDATE(), - WEEKDAY(CURDATE()) + 0 ))
    AND
        (SELECT ADDDATE(CURDATE(), - WEEKDAY(CURDATE()) + 6 ))
ORDER BY result_score DESC
    LIMIT 1;
